1	// This file implements lossless archiving of one organization's audit
2	// export. AuditExport hands back detached in-memory records and the caller
3	// separately retains the checkpoint pinning them; an archive serializes the
4	// export so it can be saved to a file when the service instance ends and
5	// read back later, still paired with the caller's own checkpoint and still
6	// usable as the material for RecheckDecisionOffline.
7	//
8	// The format is a length-delimited binary encoding built by hand rather
9	// than encoding/json: JSON text cannot carry bytes that are not valid
10	// UTF-8 without silently replacing them with U+FFFD, which would collapse
11	// genuinely different content (a lone 0xFF, a lone 0xFE and a real U+FFFD)
12	// onto identical records and change their fingerprints. Every string is
13	// written from its exact bytes with a length prefix, and nil slices,
14	// non-nil empty slices and absent payloads are each marked explicitly.
15	//
16	// Integrity never comes from trust in the file. A decode reconstructs the
17	// records and then runs the same whole-material VerifyAudit chain check
18	// against the checkpoint the caller supplies independently; the checkpoint
19	// embedded in the archive is informational only and never authoritative.
20	package darksafe
21	
22	import (
23		"bytes"
24		"crypto/sha256"
25		"encoding/binary"
26		"errors"
27		"fmt"
28	)
29	
30	// ErrInvalidArchive means archive bytes are not a recognizable, complete,
31	// untampered audit archive: a foreign/truncated/trailing-byte framing, a
32	// failed checksum, or content that does not decode. Content-level failures
33	// (missing or mismatched organization, missing, out-of-order or modified
34	// records, a mismatched checkpoint) keep using ErrMissingOrganization and
35	// ErrInvalidRange exactly as the other audit entry points do.
36	var ErrInvalidArchive = errors.New("darksafe: invalid audit archive")
37	
38	// Archive framing:
39	//
40	//	magic   = archiveMagic
41	//	u32 BE  = byte length of the payload that follows
42	//	payload = archivePayloadLen bytes
43	//	32 bytes = SHA-256 checksum of payload
44	//
45	// A second archive concatenated to a first is trailing material, not a
46	// second frame: a read consumes exactly one frame and rejects any byte
47	// beyond it.
48	const archiveMagic = "darksafe-audit-archive-v1\n"
49	
50	const (
51		archiveTagBoolFalse byte = 0
52		archiveTagBoolTrue  byte = 1
53		archiveTagNil       byte = 0
54		archiveTagPresent   byte = 1
55	)
56	
57	// archiveWriter appends length-delimited fields to a byte buffer.
58	type archiveWriter struct {
59		buf []byte
60		err error
61	}
62	
63	func (w *archiveWriter) raw(data []byte) {
64		w.buf = append(w.buf, data...)
65	}
66	
67	// u32 writes a non-negative int as a big-endian uint32.
68	func (w *archiveWriter) u32(v int) {
69		if v < 0 || uint64(v) > 0xffffffff {
70			w.err = fmt.Errorf("%w: length out of range: %d", ErrInvalidArchive, v)
71			return
72		}
73		var b [4]byte
74		binary.BigEndian.PutUint32(b[:], uint32(v))
75		w.buf = append(w.buf, b[:]...)
76	}
77	
78	func (w *archiveWriter) boolean(v bool) {
79		if v {
80			w.buf = append(w.buf, archiveTagBoolTrue)
81		} else {
82			w.buf = append(w.buf, archiveTagBoolFalse)
83		}
84	}
85	
86	// stringField writes a string from its exact memory bytes. Nothing is
87	// validated, replaced or normalized: a lone 0xFF reaches the output as
88	// itself and stays distinguishable from 0xFE and a genuine U+FFFD.
89	func (w *archiveWriter) stringField(s string) {
90		w.u32(len(s))
91		if w.err != nil {
92			return
93		}
94		w.buf = append(w.buf, s...)
95	}
96	
97	// stringList preserves the slice shape explicitly: nil is one marker, a
98	// non-nil list is a marker, a count and the raw strings.
99	func (w *archiveWriter) stringList(items []string) {
100		if items == nil {
101			w.buf = append(w.buf, archiveTagNil)
102			return
103		}
104		w.buf = append(w.buf, archiveTagPresent)
105		w.u32(len(items))
106		for _, s := range items {
107			w.stringField(s)
108		}
109	}
110	
111	// policy writes one Policy by walking the single policy field table, so the
112	// archive's field order is the fingerprint's order by construction. Even the
113	// fingerprint-optional ResourceID is always written here (empty included),
114	// so every field round trips on its own; its placement is fixed by the
115	// table and therefore cannot move a fingerprint boundary.
116	func (w *archiveWriter) policy(p Policy) {
117		for i := range policyFields {
118			f := &policyFields[i]
119			switch f.kind {
120			case policyFieldString, policyFieldOptionalString:
121				w.stringField(f.getString(p))
122			case policyFieldBool:
123				w.boolean(f.getBool(p))
124			}
125		}
126	}
127	
128	func (w *archiveWriter) policyList(policies []Policy) {
129		if policies == nil {
130			w.buf = append(w.buf, archiveTagNil)
131			return
132		}
133		w.buf = append(w.buf, archiveTagPresent)
134		w.u32(len(policies))
135		for _, p := range policies {
136			w.policy(p)
137		}
138	}
139	
140	// change writes the policy-change payload, or a single absence marker:
141	// VerifyAudit only ever accepts a change payload on a policy-change record
142	// and its absence otherwise, but the distinction is encoded explicitly so
143	// decode never has to reconstruct a shape. A present payload walks the
144	// single policy-change field table, so the archive's field order is the
145	// fingerprint's order by construction and every change field round trips.
146	func (w *archiveWriter) change(c *PolicyChange) {
147		if c == nil {
148			w.buf = append(w.buf, archiveTagNil)
149			return
150		}
151		w.buf = append(w.buf, archiveTagPresent)
152		for i := range changeFields {
153			f := &changeFields[i]
154			switch f.kind {
155			case changeFieldInt:
156				w.u32(f.getInt(c))
157			case changeFieldPolicyList:
158				w.policyList(f.getPolicies(c))
159			case changeFieldBool:
160				w.boolean(f.getBool(c))
161			}
162		}
163	}
164	
165	// decisionRecord writes the decision payload, or a single absence marker:
166	// VerifyAudit only ever accepts a decision payload on a decision record and
167	// its absence otherwise, but the distinction is encoded explicitly so decode
168	// never has to reconstruct a shape. A present payload walks the single
169	// decision field table, so the archive's field order is the fingerprint's
170	// order by construction and every request and decision field round trips.
171	func (w *archiveWriter) decisionRecord(d *DecisionRecord) {
172		if d == nil {
173			w.buf = append(w.buf, archiveTagNil)
174			return
175		}
176		w.buf = append(w.buf, archiveTagPresent)
177		for i := range decisionFields {
178			f := &decisionFields[i]
179			switch f.kind {
180			case decisionFieldString:
181				w.stringField(f.getString(d))
182			case decisionFieldStringList:
183				w.stringList(f.getList(d))
184			case decisionFieldBool:
185				w.boolean(f.getBool(d))
186			case decisionFieldInt:
187				w.u32(f.getInt(d))
188			}
189		}
190	}
191	
192	// EncodeAuditArchive serializes one complete audit export into savable
193	// bytes. org is the organization name, records is its complete chain from
194	// sequence 1 (a valid prefix ending at some historical sequence is enough,
195	// provided cp pins exactly that sequence), and cp is the checkpoint the
196	// caller separately retains. An organization with no records archives too:
197	// records is empty and cp is its sequence-0 genesis checkpoint.
198	//
199	// The whole material is validated exactly as VerifyAudit would before any
200	// bytes are returned: a missing organization is ErrMissingOrganization, and
201	// a missing, out-of-order or foreign record, modified content or checkpoint
202	// mismatch is ErrInvalidRange. On failure no archive bytes are returned.
203	// The checkpoint is carried in the archive for reference, but never stands
204	// in for the separately retained evidence: DecodeAuditArchive always
205	// validates against the checkpoint handed to it. The call is read-only:
206	// neither the records nor any service state are mutated and no audit record
207	// is appended.
208	func EncodeAuditArchive(org string, records []AuditRecord, cp Checkpoint) ([]byte, error) {
209		if org == "" {
210			return nil, ErrMissingOrganization
211		}
212		if err := VerifyAudit(org, records, cp); err != nil {
213			return nil, err
214		}
215	
216		pw := &archiveWriter{}
217		pw.stringField(org)
218		pw.u32(cp.EndSeq)
219		pw.stringField(cp.Fingerprint)
220		pw.u32(len(records))
221		for i := range records {
222			rec := &records[i]
223			// The outer record fields walk the single record field table, so
224			// the archive's record layout is the fingerprint envelope's layout
225			// — plus the record's own fingerprint, which the envelope excludes
226			// — by construction, and no outer field can be skipped or
227			// reordered here alone.
228			for j := range recordFields {
229				f := &recordFields[j]
230				switch f.kind {
231				case recordFieldString:
232					pw.stringField(f.getString(rec))
233				case recordFieldInt:
234					pw.u32(f.getInt(rec))
235				case recordFieldChange:
236					pw.change(f.getChange(rec))
237				case recordFieldDecision:
238					pw.decisionRecord(f.getDecision(rec))
239				}
240			}
241		}
242		if pw.err != nil {
243			return nil, pw.err
244		}
245		payload := pw.buf
246	
247		out := make([]byte, 0, len(archiveMagic)+4+len(payload)+sha256.Size)
248		out = append(out, archiveMagic...)
249		var lenBuf [4]byte
250		binary.BigEndian.PutUint32(lenBuf[:], uint32(len(payload)))
251		out = append(out, lenBuf[:]...)
252		out = append(out, payload...)
253		sum := sha256.Sum256(payload)
254		out = append(out, sum[:]...)
255		return out, nil
256	}
257	
258	// archiveReader walks one payload without copying string contents: string
259	// fields are backed by the payload slice itself, which is owned by the
260	// decoder and never returned, so callers cannot mutate the input through
261	// the result.
262	type archiveReader struct {
263		data []byte
264		pos  int
265		err  error
266	}
267	
268	func (r *archiveReader) need(n int) bool {
269		if r.err != nil {
270			return false
271		}
272		if n < 0 || r.pos > len(r.data)-n {
273			r.err = fmt.Errorf("%w: truncated archive payload", ErrInvalidArchive)
274			return false
275		}
276		return true
277	}
278	
279	func (r *archiveReader) marker() byte {
280		if !r.need(1) {
281			return 0
282		}
283		b := r.data[r.pos]
284		r.pos++
285		return b
286	}
287	
288	func (r *archiveReader) u32() int {
289		if !r.need(4) {
290			return 0
291		}
292		v := int(binary.BigEndian.Uint32(r.data[r.pos : r.pos+4]))
293		r.pos += 4
294		return v
295	}
296	
297	// boundedCount reads a count and proves at least minBytesPerItem bytes
298	// remain per item, so a hostile payload cannot drive a huge allocation
299	// with a count its body could never satisfy.
300	func (r *archiveReader) boundedCount(minBytesPerItem int) int {
301		n := r.u32()
302		if r.err != nil {
303			return 0
304		}
305		if n < 0 || uint64(n)*uint64(minBytesPerItem) > uint64(len(r.data)-r.pos) {
306			r.err = fmt.Errorf("%w: implausible list count %d", ErrInvalidArchive, n)
307			return 0
308		}
309		return n
310	}
311	
312	func (r *archiveReader) boolean() bool {
313		switch r.marker() {
314		case archiveTagBoolTrue:
315			return true
316		case archiveTagBoolFalse:
317			return false
318		default:
319			if r.err == nil {
320				r.err = fmt.Errorf("%w: invalid boolean marker", ErrInvalidArchive)
321			}
322			return false
323		}
324	}
325	
326	func (r *archiveReader) stringField() string {
327		n := r.u32()
328		if r.err != nil {
329			return ""
330		}
331		if !r.need(n) {
332			return ""
333		}
334		// Conversion copies the bytes, so the result never aliases the input.
335		s := string(r.data[r.pos : r.pos+n])
336		r.pos += n
337		return s
338	}
339	
340	func (r *archiveReader) stringList() []string {
341		switch r.marker() {
342		case archiveTagNil:
343			return nil
344		case archiveTagPresent:
345		default:
346			if r.err == nil {
347				r.err = fmt.Errorf("%w: invalid list marker", ErrInvalidArchive)
348			}
349			return nil
350		}
351		n := r.boundedCount(4) // each item carries at least one length word
352		if r.err != nil {
353			return nil
354		}
355		items := make([]string, n)
356		for i := range items {
357			items[i] = r.stringField()
358		}
359		return items
360	}
361	
362	func (r *archiveReader) policy() Policy {
363		// Read fields in the single table's (write and fingerprint) order. The
364		// fingerprint-optional ResourceID is still a mandatory, fixed field on
365		// the archive, so it is read for every policy including the empty one.
366		var p Policy
367		for i := range policyFields {
368			f := &policyFields[i]
369			switch f.kind {
370			case policyFieldString, policyFieldOptionalString:
371				f.setString(&p, r.stringField())
372			case policyFieldBool:
373				f.setBool(&p, r.boolean())
374			}
375		}
376		return p
377	}
378	
379	func (r *archiveReader) policyList() []Policy {
380		switch r.marker() {
381		case archiveTagNil:
382			return nil
383		case archiveTagPresent:
384		default:
385			if r.err == nil {
386				r.err = fmt.Errorf("%w: invalid policy list marker", ErrInvalidArchive)
387			}
388			return nil
389		}
390		// A policy writes six length words (five strings plus ResourceID) and
391		// one bool byte at minimum.
392		n := r.boundedCount(6*4 + 1)
393		if r.err != nil {
394			return nil
395		}
396		policies := make([]Policy, n)
397		for i := range policies {
398			policies[i] = r.policy()
399		}
400		return policies
401	}
402	
403	func (r *archiveReader) change() *PolicyChange {
404		switch r.marker() {
405		case archiveTagNil:
406			return nil
407		case archiveTagPresent:
408		default:
409			if r.err == nil {
410				r.err = fmt.Errorf("%w: invalid change payload marker", ErrInvalidArchive)
411			}
412			return nil
413		}
414		// Read fields in the single table's (write and fingerprint) order, so a
415		// field can never be restored into the wrong member or skipped.
416		c := &PolicyChange{}
417		for i := range changeFields {
418			f := &changeFields[i]
419			switch f.kind {
420			case changeFieldInt:
421				f.setInt(c, r.u32())
422			case changeFieldPolicyList:
423				f.setPolicies(c, r.policyList())
424			case changeFieldBool:
425				f.setBool(c, r.boolean())
426			}
427		}
428		return c
429	}
430	
431	func (r *archiveReader) decisionRecord() *DecisionRecord {
432		switch r.marker() {
433		case archiveTagNil:
434			return nil
435		case archiveTagPresent:
436		default:
437			if r.err == nil {
438				r.err = fmt.Errorf("%w: invalid decision payload marker", ErrInvalidArchive)
439			}
440			return nil
441		}
442		// Read fields in the single table's (write and fingerprint) order, so a
443		// field can never be restored into the wrong member or skipped.
444		d := &DecisionRecord{}
445		for i := range decisionFields {
446			f := &decisionFields[i]
447			switch f.kind {
448			case decisionFieldString:
449				f.setString(d, r.stringField())
450			case decisionFieldStringList:
451				f.setList(d, r.stringList())
452			case decisionFieldBool:
453				f.setBool(d, r.boolean())
454			case decisionFieldInt:
455				f.setInt(d, r.u32())
456			}
457		}
458		return d
459	}
460	
461	// DecodeAuditArchive reads one archive produced by EncodeAuditArchive and
462	// returns records that can be handed directly to RecheckDecisionOffline.
463	// org is the organization the caller expects, and cp is the checkpoint the
464	// caller independently retained; the checkpoint embedded in the file is
465	// never treated as evidence, so even an archive carrying a plausible
466	// checkpoint only validates against the one supplied here.
467	//
468	// A missing organization is ErrMissingOrganization. Unrecognized framing,
469	// truncation, a trailing second archive or any other extra byte, a bad
470	// checksum, and undecodable content are ErrInvalidArchive. Records that
471	// decode but are missing, out of order, foreign to the organization,
472	// modified (including a record after the one the caller intends to review)
473	// or mismatched with the supplied checkpoint fail the whole read with
474	// ErrInvalidRange. Failure returns no records. A successful read only
475	// proves the material matches the checkpoint: an original decision that
476	// disagrees with a recomputed one is reported later by offline review, not
477	// treated as archive damage. The result is detached from archive (mutating
478	// one never reaches the other), and the call is read-only.
479	func DecodeAuditArchive(archive []byte, org string, cp Checkpoint) ([]AuditRecord, error) {
480		if org == "" {
481			return nil, ErrMissingOrganization
482		}
483		magicLen := len(archiveMagic)
484		if len(archive) < magicLen+4+sha256.Size || string(archive[:magicLen]) != archiveMagic {
485			return nil, fmt.Errorf("%w: unrecognized audit archive", ErrInvalidArchive)
486		}
487		pos := magicLen
488		payloadLen := int(binary.BigEndian.Uint32(archive[pos : pos+4]))
489		pos += 4
490		checksumEnd := pos + payloadLen
491		if payloadLen < 0 || checksumEnd+sha256.Size != len(archive) {
492			// A short frame is truncation; bytes beyond the one frame (a
493			// concatenated second archive, junk appended to a good file) are a
494			// framing failure too.
495			return nil, fmt.Errorf("%w: truncated or trailing audit archive bytes", ErrInvalidArchive)
496		}
497		payload := archive[pos:checksumEnd]
498		sum := sha256.Sum256(payload)
499		if !bytes.Equal(sum[:], archive[checksumEnd:checksumEnd+sha256.Size]) {
500			return nil, fmt.Errorf("%w: checksum mismatch", ErrInvalidArchive)
501		}
502	
503		r := &archiveReader{data: payload}
504		embeddedOrg := r.stringField()
505		embeddedEndSeq := r.u32()
506		embeddedFingerprint := r.stringField()
507		// Every record writes two payload markers, a sequence word, two
508		// fingerprint length words and org/kind length words: 22 bytes even
509		// when every string is empty.
510		n := r.boundedCount(22)
511		if r.err != nil {
512			return nil, r.err
513		}
514		records := make([]AuditRecord, 0, n)
515		for i := 0; i < n; i++ {
516			// Read the outer fields in the single record field table's (write
517			// and fingerprint) order, so a field can never be restored into
518			// the wrong member or skipped.
519			var rec AuditRecord
520			for j := range recordFields {
521				f := &recordFields[j]
522				switch f.kind {
523				case recordFieldString:
524					f.setString(&rec, r.stringField())
525				case recordFieldInt:
526					f.setInt(&rec, r.u32())
527				case recordFieldChange:
528					f.setChange(&rec, r.change())
529				case recordFieldDecision:
530					f.setDecision(&rec, r.decisionRecord())
531				}
532			}
533			records = append(records, rec)
534		}
535		if r.err != nil {
536			return nil, r.err
537		}
538		if r.pos != len(payload) {
539			return nil, fmt.Errorf("%w: %d unconsumed archive bytes", ErrInvalidArchive, len(payload)-r.pos)
540		}
541	
542		// Content checks reuse the exact audit-range validation the live export
543		// and offline review paths use, so an archive can never smuggle in a
544		// shape those entry points would reject.
545		if embeddedOrg != org {
546			return nil, fmt.Errorf("%w: archive organization %q does not match %q", ErrInvalidRange, embeddedOrg, org)
547		}
548		// The embedded checkpoint is informational; still, contradicting its own
549		// header means the payload was altered, and the authoritative check
550		// below always uses the caller's independently retained checkpoint.
551		if embeddedEndSeq != cp.EndSeq || embeddedFingerprint != cp.Fingerprint {
552			return nil, fmt.Errorf("%w: embedded checkpoint does not match the retained checkpoint", ErrInvalidRange)
553		}
554		if err := VerifyAudit(org, records, cp); err != nil {
555			return nil, err
556		}
557		return records, nil
558	}
559

