304		}
305	
306		// A well-fingerprinted record whose payload does not match its kind.
307		wrongPayload := syntheticRecord("acme", 1, AuditDecision, &PolicyChange{Version: 1}, nil, genesisFingerprint("acme"))
308		if b, err := EncodeAuditArchive("acme", []AuditRecord{wrongPayload},
309			Checkpoint{Org: "acme", EndSeq: 1, Fingerprint: wrongPayload.Fingerprint}); !errors.Is(err, ErrInvalidRange) || b != nil {
310			t.Fatalf("payload/kind mismatch: bytes=%v err=%v", b, err)
311		}
312	}
313	
314	// reframe parses one archive frame, lets the test alter the payload, and
315	// rebuilds a frame with a consistent declared length and checksum so the
316	// failure under test is content validation, not framing.
317	func reframe(t *testing.T, archive []byte, mutate func(payload []byte) []byte) []byte {
318		t.Helper()
319		magicLen := len(archiveMagic)
320		n := int(binary.BigEndian.Uint32(archive[magicLen : magicLen+4]))
321		payload := append([]byte(nil), archive[magicLen+4:magicLen+4+n]...)
322		payload = mutate(payload)
323		out := append([]byte(nil), archiveMagic...)
324		var lb [4]byte
325		binary.BigEndian.PutUint32(lb[:], uint32(len(payload)))
326		out = append(out, lb[:]...)
327		out = append(out, payload...)
328		sum := sha256.Sum256(payload)
329		out = append(out, sum[:]...)
330		return out
331	}
332	
333	// TestArchiveDecodeFramingErrors covers every framing failure mode.
334	func TestArchiveDecodeFramingErrors(t *testing.T) {
335		s := NewStore()
336		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
337		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
338		recs, cp, err := s.AuditExport("acme", 0)
339		if err != nil {
340			t.Fatal(err)
341		}
342		good, err := EncodeAuditArchive("acme", recs, cp)
343		if err != nil {
344			t.Fatal(err)
345		}
346	
347		mustFail := func(name string, data []byte) {
348			t.Helper()
349			got, err := DecodeAuditArchive(data, "acme", cp)
350			if !errors.Is(err, ErrInvalidArchive) || got != nil {
351				t.Fatalf("%s: records=%v err=%v, want ErrInvalidArchive and no records", name, got, err)
352			}
353		}
354		mustFail("nil", nil)
355		mustFail("empty", []byte{})
356		mustFail("garbage", []byte("this is certainly not an audit archive"))
357		mustFail("almost magic", append([]byte(archiveMagic[:len(archiveMagic)-1]), 'x'))
358		// Truncations at every boundary class.
359		for _, cut := range []int{1, 4, 31, 32, 33, len(archiveMagic), len(archiveMagic) + 1, len(good) - 1} {
360			if cut < len(good) {
361				mustFail(fmt.Sprintf("truncated %d", cut), good[:cut])
362			}
363		}
364		// Flip a byte in the magic.
365		flip := append([]byte(nil), good...)
366		flip[0] ^= 0x80
367		mustFail("bad magic", flip)
368		// Declared length beyond the actual file.
369		tooLong := append([]byte(nil), good...)
370		binary.BigEndian.PutUint32(tooLong[len(archiveMagic):], binary.BigEndian.Uint32(tooLong[len(archiveMagic):])+100)
371		mustFail("declared length too large", tooLong)
372		// Declared length shorter: bytes of the good frame become trailing.
373		tooShort := append([]byte(nil), good...)
374		binary.BigEndian.PutUint32(tooShort[len(archiveMagic):], binary.BigEndian.Uint32(tooShort[len(archiveMagic):])-1)
375		mustFail("declared length too small", tooShort)
376		// Damage inside the payload with the original checksum left intact.
377		damaged := append([]byte(nil), good...)
378		damaged[len(archiveMagic)+5] ^= 0x01
379		mustFail("payload bitflip, stale checksum", damaged)
380		// Damage inside the checksum.
381		csumDamage := append([]byte(nil), good...)
382		csumDamage[len(csumDamage)-1] ^= 0x01
383		mustFail("checksum bitflip", csumDamage)
384		// A second full archive concatenated to the first is trailing material.
385		mustFail("concatenated second archive", append(append([]byte(nil), good...), good...))
386		// Ordinary trailing junk.
387		mustFail("trailing junk", append(append([]byte(nil), good...), 0, 1, 2, 3))
388	
389		// A content change with a recomputed checksum passes framing but must
390		// fail chain validation with ErrInvalidRange.
391		tampered := reframe(t, good, func(payload []byte) []byte {
392			idx := bytes.Index(payload, []byte("matched allow policy"))
393			if idx < 0 {
394				t.Fatal("fixture reason not found in payload")
395			}
396			payload[idx] ^= 0x01 // same length, no length prefix or marker moves
397			return payload
398		})
399		if got, err := DecodeAuditArchive(tampered, "acme", cp); !errors.Is(err, ErrInvalidRange) || got != nil {
400			t.Fatalf("checksum-valid tampered content: records=%v err=%v, want ErrInvalidRange", got, err)
401		}
402	}
403	
404	// TestArchiveDecodeContentValidation ensures decode validates the entire
405	// material against the caller's retained checkpoint and expected org.
406	func TestArchiveDecodeContentValidation(t *testing.T) {
407		s := NewStore()
408		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
409		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
410		s.Publish("acme", 1, nil)
411		s.Decide("acme", request("acme", "late-victim", "r1", "org/a", "read"))
412		recs, cp, err := s.AuditExport("acme", 0)
413		if err != nil {
414			t.Fatal(err)
415		}
416		good, err := EncodeAuditArchive("acme", recs, cp)
417		if err != nil {
418			t.Fatal(err)
419		}
420	
421		if got, err := DecodeAuditArchive(good, "", cp); !errors.Is(err, ErrMissingOrganization) || got != nil {
422			t.Fatalf("empty org decode: %v %v", got, err)
423		}
424		if _, err := DecodeAuditArchive(good, "globex", cp); !errors.Is(err, ErrInvalidRange) {
425			t.Fatalf("foreign expected org err = %v", err)
426		}
427		// The caller's checkpoint is authoritative; a wrong fingerprint and a
428		// wrong end sequence both fail, even though the embedded checkpoint
429		// matches the content.
430		for _, wrong := range []Checkpoint{
431			{Org: "acme", EndSeq: cp.EndSeq, Fingerprint: cp.Fingerprint + "x"},
432			{Org: "acme", EndSeq: cp.EndSeq - 1, Fingerprint: cp.Fingerprint},
433			{Org: "acme", EndSeq: cp.EndSeq, Fingerprint: genesisFingerprint("acme")},
434		} {
435			if _, err := DecodeAuditArchive(good, "acme", wrong); !errors.Is(err, ErrInvalidRange) {
436				t.Fatalf("checkpoint %+v err = %v, want ErrInvalidRange", wrong, err)
437			}
438		}
439	
440		// Damage confined to a record after the one the caller plans to review
441		// still fails the whole read.
442		late := reframe(t, good, func(payload []byte) []byte {
443			idx := bytes.Index(payload, []byte("late-victim"))
444			if idx < 0 {
445				t.Fatal("late record subject not found in payload")
446			}
447			payload[idx] ^= 0x01
448			return payload
449		})
450		if _, err := DecodeAuditArchive(late, "acme", cp); !errors.Is(err, ErrInvalidRange) {
451			t.Fatalf("late-record damage err = %v, want ErrInvalidRange", err)
452		}
453	
454		// An archive of another organization cannot be read as acme even with
455		// acme-shaped caller data.
456		grecs, gcp, _ := NewStore().AuditExport("globex", 0)
457		garchive, err := EncodeAuditArchive("globex", grecs, gcp)
458		if err != nil {
459			t.Fatal(err)
460		}
461		if _, err := DecodeAuditArchive(garchive, "acme", cp); !errors.Is(err, ErrInvalidRange) {
462			t.Fatalf("cross-org archive err = %v", err)
463		}
464	}
465	
466	// TestArchiveCheckpointInsideIsNotAuthority proves a file that internally
467	// carries one checkpoint still validates exclusively against the caller's.
468	func TestArchiveCheckpointInsideIsNotAuthority(t *testing.T) {
469		s := NewStore()
470		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
471		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
472		recs, cp, _ := s.AuditExport("acme", 0)
473		good, err := EncodeAuditArchive("acme", recs, cp)
474		if err != nil {
475			t.Fatal(err)
476		}
477	
478		// Re-frame the same records with a different embedded end sequence: the
479		// caller's retained checkpoint must be the one that decides.
480		rewritten := reframe(t, good, func(payload []byte) []byte {
481			// Header layout: u32 orgLen, org, u32 endSeq, u32 fpLen, fp, ...
482			pos := 4 + len("acme")
483			binary.BigEndian.PutUint32(payload[pos:pos+4], 999)
484			return payload
485		})
486		if _, err := DecodeAuditArchive(rewritten, "acme", cp); !errors.Is(err, ErrInvalidRange) {
487			t.Fatalf("altered embedded metadata must not be trusted: err = %v", err)
488		}
489	}
490	
491	// TestArchiveInconsistentDecisionIsNotArchiveDamage archives a chain that
492	// is internally valid but whose recorded decision contradicts the recorded
493	// policy: decode succeeds, and offline review reports the inconsistency.
494	func TestArchiveInconsistentDecisionIsNotArchiveDamage(t *testing.T) {
495		req := request("acme", "u1", "r1", "org/a", "read")
496		recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
497			func(seq int) (string, *PolicyChange, *DecisionRecord) {
498				return AuditPolicyChange, &PolicyChange{
499					Version:  1,
500					Policies: []Policy{allowPolicy("p1", "u1", "read", "org/a", false)},
501				}, nil
502			},
503			func(seq int) (string, *PolicyChange, *DecisionRecord) {
504				return AuditDecision, nil, &DecisionRecord{
505					Request:  req,
506					Decision: Decision{Allowed: false, Reason: "matched deny policy", Matched: []string{"p1"}, Version: 1},
507				}
508			},
509		})
510		archive, err := EncodeAuditArchive("acme", recs, cp)
511		if err != nil {
512			t.Fatal(err)
513		}
514		got, err := DecodeAuditArchive(archive, "acme", cp)
515		if err != nil {
516			t.Fatalf("a decision disagreement is not archive damage: %v", err)
517		}
518		review, err := RecheckDecisionOffline("acme", got, cp, 2)
519		if err != nil {
520			t.Fatal(err)
521		}
522		if review.Consistent {
523			t.Fatal("inconsistent decision must still be reported by offline review")
524		}
525	}
526	
527	// TestArchiveIsReadOnlyAndDetached proves encode and decode mutate nothing
528	// and return values independent of their inputs and of each other.
529	func TestArchiveIsReadOnlyAndDetached(t *testing.T) {
530		s := NewStore()
531		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
532		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
533		before, beforeCP, _ := s.AuditExport("acme", 0)
534	
535		recs, cp, _ := s.AuditExport("acme", 0)
536		snapshot := cloneExportedRecords(recs)
537		archive, err := EncodeAuditArchive("acme", recs, cp)
538		if err != nil {
539			t.Fatal(err)
540		}
541		if !reflect.DeepEqual(recs, snapshot) {
542			t.Fatal("encode mutated the supplied records")
543		}
544		// Encode/decode append nothing to any service state.
545		after, afterCP, _ := s.AuditExport("acme", 0)
546		if !reflect.DeepEqual(after, before) || afterCP != beforeCP {
547			t.Fatal("archive operations changed service state")
548		}
549	
550		got, err := DecodeAuditArchive(archive, "acme", cp)
551		if err != nil {
552			t.Fatal(err)
553		}
554		// Mutating the input bytes after decode cannot reach a prior result.
555		for i := range archive {
556			archive[i] = 0
557		}
558		if got[0].Change.Policies[0].ID != "p1" {
559			t.Fatal("decoded records alias the archive input bytes")
560		}
561		// Mutating one decoded result cannot affect a later decode.
562		got[0].Change.Policies[0].ID = "hacker"
563		got[1].Decision.Request.Subject.ID = "hacker"
564		got[1].Decision.Decision.Matched = append(got[1].Decision.Decision.Matched, "x")
565		fresh, err := EncodeAuditArchive("acme", recs, cp)
566		if err != nil {
567			t.Fatal(err)
568		}
569		again, err := DecodeAuditArchive(fresh, "acme", cp)
570		if err != nil {
571			t.Fatal(err)
572		}
573		if !reflect.DeepEqual(again, recs) {
574			t.Fatal("mutation of one decoded result reached another decode")
575		}
576	}
577	
578	// TestArchiveRoundTripAfterInstanceEnds simulates the stated lifecycle:
579	// export and archive on one instance, then (with no Store at all) read the
580	// bytes elsewhere and continue offline review against the retained
581	// checkpoint.
582	func TestArchiveRoundTripAfterInstanceEnds(t *testing.T) {
583		first := NewStore()
584		first.Publish("acme", 0, []Policy{
585			{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, ResourceID: " r 1 "},
586		})
587		original := first.Decide("acme", request("acme", "u1", " r 1 ", "org/a", "read"))
588		recs, cp, err := first.AuditExport("acme", 0)
589		if err != nil {
590			t.Fatal(err)
591		}
592		saved, err := EncodeAuditArchive("acme", recs, cp)
593		if err != nil {
594			t.Fatal(err)
595		}
596	
597		// New instance, no Store involved in decoding.
598		loaded, err := DecodeAuditArchive(saved, "acme", cp)
599		if err != nil {
600			t.Fatalf("read after instance end: %v", err)
601		}
602		review, err := RecheckDecisionOffline("acme", loaded, cp, 2)
603		if err != nil {
604			t.Fatal(err)
605		}
606		if !review.Consistent || !reflect.DeepEqual(review.Original, original) {
607			t.Fatalf("post-restart review = %+v, original %+v", review, original)
608		}
609	}
