449	// TestNonEmptyListsPreserveChineseSpacesAndRawBytes checks the byte-level
450	// content guarantee on non-empty lists: Chinese, spaces and non-UTF-8
451	// bytes in roles and matched policy ids survive as the original bytes,
452	// even after the caller edits the request, the returned decision and
453	// later read copies. The full export keeps passing its chain check,
454	// including through an archive round trip.
455	func TestNonEmptyListsPreserveChineseSpacesAndRawBytes(t *testing.T) {
456		s := NewStore()
457		policies := []Policy{
458			// Allow hit with spaces and Chinese; deny hit carrying a different
459			// invalid byte than the request does, so matched ordering exercises
460			// raw content too.
461			{ID: "通 行 策 略", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow},
462			{ID: "拒" + anotherInvalidByte + "止 策 略", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectDeny},
463			{ID: "允 许" + invalidByte + "策 略", Subject: "u2", Action: "read", Scope: "org/a", Effect: EffectAllow},
464		}
465		if _, err := s.Publish("acme", 0, policies); err != nil {
466			t.Fatal(err)
467		}
468		roles := listIsolationRoles()
469		allowReq := roleRequest("u2", roles)
470		denyReq := roleRequest("u1", roles)
471		allowD := s.Decide("acme", allowReq) // seq 2
472		denyD := s.Decide("acme", denyReq)   // seq 3
473		if !allowD.Allowed || denyD.Allowed {
474			t.Fatalf("setup decisions: allow=%+v deny=%+v", allowD, denyD)
475		}
476		if !strings.Contains(allowD.Matched[0], invalidByte) {
477			t.Fatal("test premise broken: allow hit must carry the invalid byte")
478		}
479		if !strings.Contains(denyD.Matched[0], anotherInvalidByte) {
480			t.Fatal("test premise broken: deny hit must carry the other invalid byte")
481		}
482		wantRoles := append([]string(nil), roles...)
483		wantAllow := cloneDecisionValue(allowD)
484		wantDeny := cloneDecisionValue(denyD)
485	
486		// Caller edits the submitted request lists and the returned decisions.
487		allowReq.Subject.Roles[0] = "plain replacement"
488		allowReq.Subject.Roles = append(allowReq.Subject.Roles, "尾随角色")
489		denyReq.Subject.Roles[2] = "\xfe"
490		denyReq.Subject.Roles = append(denyReq.Subject.Roles, "x")
491		allowD.Matched[0] = "plain"
492		allowD.Matched = append(allowD.Matched, "ghost")
493		denyD.Matched[0] = "plain"
494		denyD.Matched = append(denyD.Matched, "ghost")
495	
496		recs, cp, err := s.AuditExport("acme", 0)
497		if err != nil {
498			t.Fatal(err)
499		}
500		if err := VerifyAudit("acme", recs, cp); err != nil {
501			t.Fatalf("raw-byte chain after caller edits: %v", err)
502		}
503		assertDecisionListContent(t, &recs[1], 2, wantRoles, wantAllow)
504		assertDecisionListContent(t, &recs[2], 3, wantRoles, wantDeny)
505		savedRoles := recs[1].Decision.Request.Subject.Roles
506		if !strings.Contains(savedRoles[0], "角色") ||
507			!strings.HasPrefix(savedRoles[1], "  ") || !strings.HasSuffix(savedRoles[1], "  ") ||
508			!strings.Contains(savedRoles[2], invalidByte) {
509			t.Fatalf("roles lost their original bytes/spacing/order: %q", savedRoles)
510		}
511		if !strings.Contains(recordBySeq(t, recs, 2).Decision.Decision.Matched[0], invalidByte) {
512			t.Fatal("stored allow matched list lost its invalid byte")
513		}
514		if !strings.Contains(recordBySeq(t, recs, 3).Decision.Decision.Matched[0], anotherInvalidByte) {
515			t.Fatal("stored deny matched list lost its invalid byte")
516		}
517	
518		// Editing the exported copy and reading again leaves the stored bytes
519		// intact and the chain check still holds on the fresh read.
520		rewriteLists(&recs[1])
521		rewriteLists(&recs[2])
522		fresh, freshCP, err := s.AuditExport("acme", 0)
523		if err != nil {
524			t.Fatal(err)
525		}
526		if freshCP != cp {
527			t.Fatal("checkpoint changed despite list edits")
528		}
529		if err := VerifyAudit("acme", fresh, cp); err != nil {
530			t.Fatalf("fresh raw-byte export must still verify: %v", err)
531		}
532		assertDecisionListContent(t, &fresh[1], 2, wantRoles, wantAllow)
533		assertDecisionListContent(t, &fresh[2], 3, wantRoles, wantDeny)
534	
535		// Paged query bytes agree with the export's decision records.
536		if got := drainAudit(t, s, "acme", AuditDecision, ""); !reflect.DeepEqual(got, fresh[1:]) {
537			t.Fatal("paged raw-byte content differs from the export")
538		}
539	
540		// The archive preserves the exact bytes offline and stays verifiable.
541		archive, err := EncodeAuditArchive("acme", fresh, cp)
542		if err != nil {
543			t.Fatal(err)
544		}
545		decoded, err := DecodeAuditArchive(archive, "acme", cp)
546		if err != nil {
547			t.Fatalf("raw-byte archive decode: %v", err)
548		}
549		if !reflect.DeepEqual(decoded, fresh) {
550			t.Fatal("raw-byte archive round trip changed list content")
551		}
552	
553		// Offline re-computation derives matched policy ids with the same raw
554		// bytes and agrees with the preserved originals.
555		allowReview := mustOfflineReview(t, decoded, cp, 2)
556		if !allowReview.Consistent || !reflect.DeepEqual(allowReview.Original, wantAllow) {
557			t.Fatalf("raw-byte allow review = %+v, want %+v", allowReview, wantAllow)
558		}
559		if !strings.Contains(allowReview.Recomputed.Matched[0], invalidByte) {
560			t.Fatal("offline recomputation normalized the allow matched id")
561		}
562		denyReview := mustOfflineReview(t, decoded, cp, 3)
563		if !denyReview.Consistent || !reflect.DeepEqual(denyReview.Original, wantDeny) {
564			t.Fatalf("raw-byte deny review = %+v, want %+v", denyReview, wantDeny)
565		}
566		if !strings.Contains(denyReview.Recomputed.Matched[0], anotherInvalidByte) {
567			t.Fatal("offline recomputation normalized the deny matched id")
568		}
569	
570		// Nothing here appended records.
571		if got := len(drainAudit(t, s, "acme", "", "")); got != 3 {
572			t.Fatalf("records = %d, want 3; reads and edits must not append", got)
573		}
574	}
