576	// capaciousEmptyRoles returns a NON-NIL role list with no elements but spare
577	// capacity. It is the shape that exposed the isolation bug: cloning lists
578	// only when len > 0 let this list's backing array be shared between the
579	// stored record, every query/page/export copy and the caller's own slice, so
580	// appending a role to one handed-out copy overwrote the first role slot of
581	// every other copy.
582	func capaciousEmptyRoles() []string {
583		return make([]string, 0, 4)
584	}
